fn remove_duplicates(nums: Vec<i32>) -> Vec<i32> {
    let mut seen = std::collections::HashSet::new();
    let mut result = Vec::new();

    for &num in nums.iter() {
        if seen.insert(num) {
            result.push(num);
        }
    }

    result
}

fn main() {
    let nums = vec![1, 2, 2, 3, 4, 4, 5];
    let unique_nums = remove_duplicates(nums);
    println!("{:?}", unique_nums); // Output: [1, 2, 3, 4, 5]
}